1	package main
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"sync"
11		"time"
12	)
13	
14	var ErrNotFound = errors.New("task not found")
15	
16	type Task struct {
17		ID        string    `json:"id"`
18		Title     string    `json:"title"`
19		Done      bool      `json:"done"`
20		Due       Date      `json:"due"`
21		Tags      []string  `json:"tags"`
22		CreatedAt time.Time `json:"created_at"`
23	}
24	
25	// fileV2 is the on-disk format since TICKET-142.
26	type fileV2 struct {
27		Version int     `json:"version"`
28		NextID  int     `json:"next_id"`
29		Tasks   []*Task `json:"tasks"`
30	}
31	
32	type Store struct {
33		mu     sync.Mutex
34		path   string
35		nextID int
36		tasks  map[string]*Task
37	}
38	
39	func OpenStore(path string) (*Store, error) {
40		s := &Store{path: path, tasks: map[string]*Task{}, nextID: 1}
41		b, err := os.ReadFile(path)
42		if errors.Is(err, os.ErrNotExist) {
43			return s, nil
44		}
45		if err != nil {
46			return nil, err
47		}
48		var f fileV2
49		if err := json.Unmarshal(b, &f); err != nil {
50			return nil, fmt.Errorf("read %s: %w", path, err)
51		}
52		for _, t := range f.Tasks {
53			s.tasks[t.ID] = t
54		}
55		s.nextID = f.NextID
56		return s, nil
57	}
58	
59	// save writes the whole file to a temp file and renames it over the old one, so a crash
60	// mid-write never leaves a half-written tasks file.
61	func (s *Store) save() error {
62		f := fileV2{Version: 2, NextID: s.nextID, Tasks: s.sortedLocked()}
63		b, err := json.MarshalIndent(f, "", "  ")
64		if err != nil {
65			return err
66		}
67		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".tasks-*.json")
68		if err != nil {
69			return err
70		}
71		if _, err := tmp.Write(b); err != nil {
72			tmp.Close()
73			os.Remove(tmp.Name())
74			return err
75		}
76		if err := tmp.Close(); err != nil {
77			os.Remove(tmp.Name())
78			return err
79		}
80		return os.Rename(tmp.Name(), s.path)
81	}
82	
83	// IDs are zero-padded ("t0007"), so sorting the strings sorts them numerically.
84	func (s *Store) sortedLocked() []*Task {
85		out := make([]*Task, 0, len(s.tasks))
86		for _, t := range s.tasks {
87			out = append(out, t)
88		}
89		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
90		return out
91	}
92	
93	func (s *Store) List() []Task {
94		s.mu.Lock()
95		defer s.mu.Unlock()
96		var out []Task
97		for _, t := range s.sortedLocked() {
98			out = append(out, *t)
99		}
100		return out
101	}
102	
103	func (s *Store) Get(id string) (Task, error) {
104		s.mu.Lock()
105		defer s.mu.Unlock()
106		t, ok := s.tasks[id]
107		if !ok {
108			return Task{}, ErrNotFound
109		}
110		return *t, nil
111	}
112	
113	func (s *Store) Create(t Task, now time.Time) (Task, error) {
114		s.mu.Lock()
115		defer s.mu.Unlock()
116		t.ID = fmt.Sprintf("t%04d", s.nextID)
117		s.nextID++
118		t.CreatedAt = now.UTC()
119		s.tasks[t.ID] = &t
120		if err := s.save(); err != nil {
121			return Task{}, err
122		}
123		return t, nil
124	}
125	
126	// Update applies fn to the stored task and saves.
127	func (s *Store) Update(id string, fn func(*Task)) (Task, error) {
128		s.mu.Lock()
129		defer s.mu.Unlock()
130		t, ok := s.tasks[id]
131		if !ok {
132			return Task{}, fmt.Errorf("update %s: %v", id, ErrNotFound)
133		}
134		fn(t)
135		if err := s.save(); err != nil {
136			return Task{}, err
137		}
138		return *t, nil
139	}
140	
141	func (s *Store) Delete(id string) error {
142		s.mu.Lock()
143		defer s.mu.Unlock()
144		delete(s.tasks, id)
145		return s.save()
146	}
