85	func TestGetUnknown(t *testing.T) {
86		_, h := newTestServer(t)
87		if rec := do(t, h, "GET", "/tasks/t0099", ""); rec.Code != http.StatusNotFound {
88			t.Fatalf("got %d", rec.Code)
89		}
90	}
91	
92	func TestPatchMarksDone(t *testing.T) {
93		_, h := newTestServer(t)
94		do(t, h, "POST", "/tasks", `{"title":"Call the plumber"}`)
95		rec := do(t, h, "PATCH", "/tasks/t0001", `{"done":true}`)
96		if rec.Code != 200 || !decode[Task](t, rec).Done {
97			t.Fatalf("patch: %d %s", rec.Code, rec.Body)
