1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"testing"
7	)
8	
9	func TestMigrateV1(t *testing.T) {
10		p := filepath.Join(t.TempDir(), "tasks.json")
11		v1 := `[{"id":"t0001","title":"Water plants","done":false,"labels":"home","created":"2025-11-02T08:00:00Z"},
12		        {"id":"t0004","title":"Renew passport","done":true,"labels":"","created":"2025-12-01T10:30:00Z"}]`
13		if err := os.WriteFile(p, []byte(v1), 0o644); err != nil {
14			t.Fatal(err)
15		}
16		migrated, err := Migrate(p)
17		if err != nil || !migrated {
18			t.Fatalf("migrated=%v err=%v", migrated, err)
19		}
20		s, err := OpenStore(p)
21		if err != nil {
22			t.Fatal(err)
23		}
24		tasks := s.List()
25		if len(tasks) != 2 || tasks[0].Title != "Water plants" || !tasks[1].Done {
26			t.Fatalf("got %+v", tasks)
27		}
28		if len(tasks[0].Tags) != 1 || tasks[0].Tags[0] != "home" {
29			t.Fatalf("tags %v", tasks[0].Tags)
30		}
31		if s.nextID != 5 {
32			t.Fatalf("nextID %d", s.nextID)
33		}
34		if _, err := os.Stat(p + ".v1.bak"); err != nil {
35			t.Fatalf("no backup: %v", err)
36		}
37		// Running again on the v2 file is a no-op.
38		if again, err := Migrate(p); err != nil || again {
39			t.Fatalf("second run migrated=%v err=%v", again, err)
40		}
